package com.knoux.crypt.data

import com.knoux.crypt.security.DigitalSignatureService
import java.security.KeyFactory
import java.security.KeyPairGenerator
import java.security.PrivateKey
import java.security.spec.ECGenParameterSpec
import java.security.spec.PKCS8EncodedKeySpec
import java.util.Base64

/**
 * Signing service for TASK 19 (shared with the future signature studio).
 *
 * Two key origins are possible and the service always reports which one it
 * used:
 *  - [SigningKeyOrigin.KEYSTORE]: an asymmetric key generated by the Android
 *    Keystore, where the platform supports it.
 *  - [SigningKeyOrigin.VAULT_SOFTWARE]: a software key pair whose private half
 *    is stored as an encrypted vault record, so it is protected by the
 *    Keystore-rooted data-key hierarchy but is **not** hardware-backed. Some
 *    AndroidKeyStore providers ship without EC or RSA support at all, and the
 *    first device run on the itel S686LN hit exactly that.
 *
 * The signature always covers the SHA-256 digest of the content, so a stored
 * signature record never keeps the signed document.
 */
enum class SigningKeyOrigin {
    KEYSTORE,
    VAULT_SOFTWARE,
}

data class SignedArtifact(
    val algorithm: String,
    val digestHex: String,
    val signatureBase64: String,
    val publicKeySpkiBase64: String,
    val origin: SigningKeyOrigin,
)

data class SigningKeyInfo(
    val algorithm: String,
    val publicKeySpkiBase64: String,
    val origin: SigningKeyOrigin,
)

class SigningService(
    private val keystore: KeystoreManager,
    private val repository: SecretRepository,
    private val session: SessionManager,
) {
    /** Creates or loads the signing key pair and reports how it is protected. */
    suspend fun ensureKey(): SigningKeyInfo {
        val access = session.currentAccess() ?: throw VaultLockedException("The vault is locked")
        keystore.keystoreSigningKey()?.let { privateKey ->
            val publicKey = keystore.signingPublicKey()
            return SigningKeyInfo(
                algorithm = algorithmOf(privateKey),
                publicKeySpkiBase64 = DigitalSignatureService.publicKeyToBase64(publicKey),
                origin = SigningKeyOrigin.KEYSTORE,
            )
        }
        val stored = loadStoredKey(access)
        if (stored != null) {
            return SigningKeyInfo(
                algorithm = stored.algorithm,
                publicKeySpkiBase64 = stored.publicKeySpkiBase64,
                origin = SigningKeyOrigin.VAULT_SOFTWARE,
            )
        }
        val created = createSoftwareKey()
        repository.save(
            access,
            SecretKinds.SIGNING_KEY,
            SIGNING_KEY_ID,
            SecretsJson.encodeSigningKey(created),
        )
        return SigningKeyInfo(
            algorithm = created.algorithm,
            publicKeySpkiBase64 = created.publicKeySpkiBase64,
            origin = SigningKeyOrigin.VAULT_SOFTWARE,
        )
    }

    suspend fun sign(content: ByteArray): SignedArtifact {
        val access = session.currentAccess() ?: throw VaultLockedException("The vault is locked")
        val keystoreKey = keystore.keystoreSigningKey()
        val privateKey: PrivateKey
        val algorithm: String
        val publicKeyBase64: String
        val origin: SigningKeyOrigin
        if (keystoreKey != null) {
            privateKey = keystoreKey
            algorithm = algorithmOf(keystoreKey)
            publicKeyBase64 = DigitalSignatureService.publicKeyToBase64(keystore.signingPublicKey())
            origin = SigningKeyOrigin.KEYSTORE
        } else {
            val stored = loadStoredKey(access) ?: run {
                val created = createSoftwareKey()
                repository.save(
                    access,
                    SecretKinds.SIGNING_KEY,
                    SIGNING_KEY_ID,
                    SecretsJson.encodeSigningKey(created),
                )
                created
            }
            privateKey = privateKeyFrom(stored.privateKeyPkcs8Base64)
            algorithm = stored.algorithm
            publicKeyBase64 = stored.publicKeySpkiBase64
            origin = SigningKeyOrigin.VAULT_SOFTWARE
        }
        val signature = DigitalSignatureService.sign(content, privateKey, algorithm)
        return SignedArtifact(
            algorithm = algorithm,
            digestHex = DigitalSignatureService.digestHex(content),
            signatureBase64 = DigitalSignatureService.signatureToBase64(signature),
            publicKeySpkiBase64 = publicKeyBase64,
            origin = origin,
        )
    }

    suspend fun publicKeyBase64(): String = ensureKey().publicKeySpkiBase64

    private suspend fun loadStoredKey(access: VaultAccess): SigningKeyPayload? {
        val record = runCatching { repository.find(access, SIGNING_KEY_ID) }.getOrNull() ?: return null
        if (record.decryptionFailed) return null
        return SecretsJson.decodeSigningKey(record.payloadJson)
    }

    private fun createSoftwareKey(): SigningKeyPayload {
        val generator = KeyPairGenerator.getInstance("EC")
        generator.initialize(ECGenParameterSpec(DigitalSignatureService.CURVE))
        val pair = generator.generateKeyPair()
        return SigningKeyPayload(
            algorithm = DigitalSignatureService.ALGORITHM_ECDSA,
            privateKeyPkcs8Base64 = Base64.getEncoder().encodeToString(pair.private.encoded),
            publicKeySpkiBase64 = Base64.getEncoder().encodeToString(pair.public.encoded),
            createdAt = System.currentTimeMillis(),
        )
    }

    private fun privateKeyFrom(base64: String): PrivateKey {
        val bytes = Base64.getDecoder().decode(base64)
        return KeyFactory.getInstance("EC").generatePrivate(PKCS8EncodedKeySpec(bytes))
    }

    private fun algorithmOf(key: PrivateKey): String =
        if (key is java.security.interfaces.ECPrivateKey) {
            DigitalSignatureService.ALGORITHM_ECDSA
        } else {
            DigitalSignatureService.ALGORITHM_RSA
        }

    companion object {
        const val SIGNING_KEY_ID = "knoux.signing-key.v1"
    }
}

/** The software signing key, stored encrypted inside the vault. */
@kotlinx.serialization.Serializable
data class SigningKeyPayload(
    val algorithm: String,
    val privateKeyPkcs8Base64: String,
    val publicKeySpkiBase64: String,
    val createdAt: Long,
)
